preConditionHook:
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh N-term
// sum: seeded with a full sum on the study's first calculated bar, thereafter
// carrying S += TrueRange - TrueRange[Length], re-seeding when the length
// changes. Same block as AtrProfitTarget and AtrAboveAverage, including the TWO
// separate accumulator statements -- EasyLanguage evaluates
// Summation[1] + Price - Price[Length] left to right, and folding it to
// S += in - out rounds differently.
if (atrLenState != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLenState = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrValue = atrSum / (int)atrLookback;
// EL: the peak is taken over the atrValue VARIABLE's own history, bars 1..N,
// and an EL variable holds its initial 0 for every bar before the strategy's
// first evaluated one -- so through warm-up the peak is 0 and the filter passes
// trivially, exactly as AtrAboveAverage's mean does. The history is mirrored
// here as a zero-seeded ring buffer, re-seeded if the length ever changes.
// The scan runs NEWEST FIRST -- seeded at atrValue[1], scanning [2]..[N] with a
// strict comparison -- which is what EasyLanguage's own loop over the variable
// does, so an el_gt near-tie resolves on the same element in both twins.
if (atrHistory.size() != (std::size_t)(int)extremeLookback) {
    atrHistory.assign((std::size_t)(int)extremeLookback, 0.0);
    atrCursor = 0;
}
const std::size_t histLen = atrHistory.size();
atrPeak = atrHistory[(atrCursor + histLen - 1) % histLen];
for (std::size_t k = 2; k <= histLen; ++k) {
    double v = atrHistory[(atrCursor + histLen - k) % histLen];
    if (el_gt(v, atrPeak)) atrPeak = v;
}
// Only now does this bar's value enter the history, so the peak above is over
// bars 1..N and never includes bar 0.
atrHistory[atrCursor] = atrValue;
atrCursor = (atrCursor + 1) % histLen;
